fn numpy_matrix_transpose(x: Vec<Vec<f32>>) -> Vec<Vec<f32>> {
    // Get dimensions
    let m = x.len();  // number of rows in input
    let n = x[0].len();  // number of columns in input
    
    // Initialize result matrix with n rows
    let mut result = Vec::with_capacity(n);
    
    // Pre-allocate each row with capacity m
    for _ in 0..n {
        result.push(Vec::with_capacity(m));
    }
    
    // Fill the transposed matrix
    for i in 0..m {
        for j in 0..n {
            result[j].push(x[i][j]);
        }
    }
    
    result
}